import { defineCollection } from 'astro:content';
import { glob } from 'astro/loaders';
import { z } from 'astro/zod';

/**
 * The articles republished from bradenwong.com.
 *
 * Every file in this collection is generated by `scripts/project-editions.ts`
 * from an approved Vault edition named in `syndication.json`, and committed.
 * Nothing here is authored in this repository, and the build never reads the
 * Vault: a clone with no Vault beside it produces the deployed site exactly.
 *
 * Dates stay strings in `YYYY-MM-DD` form. A `Date` parsed from a bare day is
 * midnight UTC, which renders as the previous day for most of the Americas, and
 * an article dated a day early is a small lie the site does not need to tell.
 */
const writing = defineCollection({
	loader: glob({ pattern: '**/*.md', base: './src/content/writing' }),
	schema: z.object({
		title: z.string(),
		subtitle: z.string().optional(),
		/** The day the work was written, which can predate its release by years. */
		writtenOn: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
		/** The day its release round was approved, and so reached readers. */
		approvedOn: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
		editionId: z.uuid(),
		/** The permanent home of this work. Article pages canonicalize here. */
		canonicalUrl: z.url(),
		/** That release round's own stable address at the canonical home. */
		editionUrl: z.url(),
		tags: z.array(z.string()).default([]),
		/** The approved narration, served by the canonical home. */
		narrationUrl: z.url().optional(),
		/** The approved short video and the cover generated with it. */
		video: z.object({ src: z.url(), poster: z.url() }).optional(),
	}),
});

export const collections = { writing };
